create table public.transferencias_stock(id uuid primary key default gen_random_uuid(),numero bigint generated by default as identity unique,origen_id uuid not null references public.locations(id),destino_id uuid not null references public.locations(id),estado text not null default 'borrador' check(estado in('borrador','en_transito','recibida','cancelada')),creado_por uuid not null references public.staff(id),despachado_por uuid references public.staff(id),recibido_por uuid references public.staff(id),fecha_creacion timestamptz not null default now(),fecha_despacho timestamptz,fecha_recepcion timestamptz,observacion text,check(origen_id<>destino_id));
create table public.transferencia_stock_items(id uuid primary key default gen_random_uuid(),transferencia_id uuid not null references public.transferencias_stock(id) on delete cascade,variant_id uuid not null references public.product_variants(id),cantidad integer not null check(cantidad>0),unique(transferencia_id,variant_id));
alter table public.transferencias_stock enable row level security; alter table public.transferencia_stock_items enable row level security;
create policy transferencias_read on public.transferencias_stock for select to authenticated using(private.auth_is_admin() or origen_id=private.auth_location_id() or destino_id=private.auth_location_id());
create policy transferencia_items_read on public.transferencia_stock_items for select to authenticated using(exists(select 1 from public.transferencias_stock t where t.id=transferencia_id and(private.auth_is_admin() or t.origen_id=private.auth_location_id() or t.destino_id=private.auth_location_id())));
create or replace function public.crear_transferencia_stock(p_destino_id uuid,p_items jsonb,p_observacion text default null) returns public.transferencias_stock language plpgsql security definer set search_path='public','private' as $$ declare s public.staff;t public.transferencias_stock;x jsonb;begin if not private.auth_is_admin() then raise exception 'Solo administradores';end if;select * into s from public.staff where user_id=auth.uid() and activo=true limit 1;if s.id is null then raise exception 'Personal inválido';end if;if p_destino_id=s.location_id then raise exception 'Origen y destino no pueden ser iguales';end if;if p_items is null or jsonb_array_length(p_items)=0 then raise exception 'Transferencia vacía';end if;insert into public.transferencias_stock(origen_id,destino_id,creado_por,observacion) values(s.location_id,p_destino_id,s.id,nullif(btrim(p_observacion),'')) returning * into t;for x in select * from jsonb_array_elements(p_items) loop insert into public.transferencia_stock_items(transferencia_id,variant_id,cantidad) values(t.id,(x->>'variant_id')::uuid,(x->>'cantidad')::int);end loop;return t;end $$;
create or replace function public.despachar_transferencia_stock(p_transferencia_id uuid) returns public.transferencias_stock language plpgsql security definer set search_path='public','private' as $$ declare s public.staff;t public.transferencias_stock;i public.transferencia_stock_items;begin select * into s from public.staff where user_id=auth.uid() and activo=true limit 1;if s.id is null or not(s.rol='administrador' or s.puesto in('tecnico','encargado','jefa')) then raise exception 'Sin permiso';end if;select * into t from public.transferencias_stock where id=p_transferencia_id for update;if t.id is null or t.origen_id<>s.location_id or t.estado<>'borrador' then raise exception 'Transferencia no despachable';end if;for i in select * from public.transferencia_stock_items where transferencia_id=t.id loop update public.inventory set cantidad=cantidad-i.cantidad,updated_at=now() where variant_id=i.variant_id and location_id=t.origen_id and cantidad>=i.cantidad;if not found then raise exception 'Stock insuficiente para transferencia';end if;insert into public.inventory_movements(variant_id,location_id,cantidad_delta,motivo,staff_id) values(i.variant_id,t.origen_id,-i.cantidad,'Transferencia # '||t.numero||' despachada',s.id);end loop;update public.transferencias_stock set estado='en_transito',despachado_por=s.id,fecha_despacho=now() where id=t.id returning * into t;return t;end $$;
create or replace function public.recibir_transferencia_stock(p_transferencia_id uuid) returns public.transferencias_stock language plpgsql security definer set search_path='public','private' as $$ declare s public.staff;t public.transferencias_stock;i public.transferencia_stock_items;begin select * into s from public.staff where user_id=auth.uid() and activo=true limit 1;if s.id is null or not(s.rol='administrador' or s.puesto in('tecnico','encargado','jefa')) then raise exception 'Sin permiso';end if;select * into t from public.transferencias_stock where id=p_transferencia_id for update;if t.id is null or t.destino_id<>s.location_id or t.estado<>'en_transito' then raise exception 'Transferencia no recibible';end if;for i in select * from public.transferencia_stock_items where transferencia_id=t.id loop insert into public.inventory(variant_id,location_id,cantidad) values(i.variant_id,t.destino_id,i.cantidad) on conflict(variant_id,location_id) do update set cantidad=public.inventory.cantidad+excluded.cantidad,updated_at=now();insert into public.inventory_movements(variant_id,location_id,cantidad_delta,motivo,staff_id) values(i.variant_id,t.destino_id,i.cantidad,'Transferencia # '||t.numero||' recibida',s.id);end loop;update public.transferencias_stock set estado='recibida',recibido_por=s.id,fecha_recepcion=now() where id=t.id returning * into t;return t;end $$;
grant execute on function public.crear_transferencia_stock(uuid,jsonb,text) to authenticated;grant execute on function public.despachar_transferencia_stock(uuid) to authenticated;grant execute on function public.recibir_transferencia_stock(uuid) to authenticated;
create trigger audit_transferencias_stock after insert or update or delete on public.transferencias_stock for each row execute function private.registrar_auditoria();